+  font-weight:800;
+  letter-spacing:-.02em;
+}
+.brand-mark{
+  width:40px;height:40px;border-radius:14px;
+  background:conic-gradient(from 180deg, rgba(45,106,79,.95), rgba(242,201,76,.95), rgba(244,162,97,.95), rgba(45,106,79,.95));
