+  border:1px solid rgba(14,27,20,.12);
+  position:relative;
+  overflow:hidden;
+}
+.brand-mark:after{
+  content:"";
+  position:absolute;inset:-1px;
+  background:radial-gradient(20px 18px at 30% 28%, rgba(255,255,255,.66), transparent 60%);
+}
+.brand-name{display:flex;flex-direction:column;line-height:1.05}
+.brand-name strong{font-size:15px}
+.brand-name span{font-size:12px;color:var(--muted-2);font-weight:650}
+
+.nav{display:none;gap:22px;align-items:center}
+.nav a{font-size:14px;color:var(--muted);font-weight:650}
+.nav a:hover{color:var(--text);text-decoration:none}
+
+.header-actions{display:flex;gap:10px;align-items:center}
+
+.btn{
+  display:inline-flex;align-items:center;justify-content:center;gap:10px;
+  padding:10px 14px;
+  border-radius:999px;
+  border:1px solid var(--stroke);
+  background:var(--surface);
+  color:var(--text);
+  font-weight:750;
+  font-size:14px;
+  cursor:pointer;
+  box-shadow:0 10px 24px rgba(14,27,20,.10);
+  transition:transform .12s ease, box-shadow .12s ease, background .12s ease;
+}
+.btn:hover{transform:translateY(-1px);box-shadow:0 14px 30px rgba(14,27,20,.12)}
+.btn:active{transform:translateY(0)}
+.btn:focus{outline:none;box-shadow:0 0 0 6px var(--ring), 0 14px 30px rgba(14,27,20,.14)}
+.btn-primary{background:linear-gradient(180deg, rgba(45,106,79,1), rgba(27,77,56,1));border-color:rgba(0,0,0,.0);color:#fff}
+.btn-primary:hover{box-shadow:0 18px 40px rgba(45,106,79,.22)}
+.btn-secondary{background:linear-gradient(180deg, rgba(244,162,97,1), rgba(231,111,81,1));border-color:rgba(0,0,0,.0);color:#fff}
+.btn-secondary:hover{box-shadow:0 18px 40px rgba(231,111,81,.18)}
+.btn-ghost{background:transparent;border-color:rgba(14,27,20,.18);box-shadow:none}
+
+.icon{
+  width:18px;height:18px;display:inline-block;vertical-align:middle
+}
+
+/* Sections */
+section{padding:64px 0}
+.section-title{font-size:30px;letter-spacing:-.02em;margin:0 0 8px}
+.section-subtitle{margin:0;color:var(--muted);max-width:58ch}
+
+.pill{
+  display:inline-flex;align-items:center;gap:10px;
+  padding:8px 12px;border-radius:999px;
+  background:rgba(255,255,255,.6);
+  border:1px solid rgba(14,27,20,.10);
+  box-shadow:0 12px 32px rgba(14,27,20,.06);
+  color:rgba(14,27,20,.75);
+  font-weight:750;
+  font-size:13px;
+}
+
+/* Hero */
+.hero{padding:44px 0 38px}
+.hero-grid{display:grid;grid-template-columns:1fr;gap:26px;align-items:center}
+.hero h1{font-size:44px;line-height:1.02;margin:12px 0 10px;letter-spacing:-.04em}
+.hero p{margin:0 0 18px;color:var(--muted);font-size:16px}
+.hero-ctas{display:flex;flex-wrap:wrap;gap:12px;align-items:center}
+.hero-card{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(14,27,20,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.72), rgba(255,255,255,.50));
+  box-shadow:var(--shadow);
+  overflow:hidden;
+  position:relative;
+  min-height:340px;
+}
+.hero-photo{
+  position:absolute;inset:0;
+  background:
+    linear-gradient(180deg, rgba(254,250,224,.15), rgba(45,106,79,.20)),
+    url("https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1500&q=80");
+  background-size:cover;
+  background-position:center;
+  transform:scale(1.02);
+}
+.hero-card-content{position:relative;padding:22px;display:flex;flex-direction:column;gap:14px;min-height:340px;justify-content:flex-end}
+.hero-badges{display:flex;flex-wrap:wrap;gap:10px}
+.badge{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:10px 12px;
+  background:rgba(255,255,255,.72);
+  border:1px solid rgba(255,255,255,.60);
+  border-radius:999px;
+  box-shadow:0 14px 34px rgba(14,27,20,.10);
+  font-weight:800;font-size:13px
+}
+.badge .dot{width:10px;height:10px;border-radius:999px;background:var(--sun);box-shadow:0 0 0 5px rgba(242,201,76,.22)}
+.badge.alt .dot{background:var(--accent)}
+.badge.green .dot{background:var(--primary)}
+
+/* Highlights banner */
+.highlights{
+  padding:0;
+}
+.highlights-wrap{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(14,27,20,.12);
+  background:linear-gradient(135deg, rgba(45,106,79,1) 0%, rgba(27,77,56,1) 48%, rgba(14,27,20,1) 100%);
+  color:#fff;
+  box-shadow:0 24px 70px rgba(14,27,20,.22);
+  overflow:hidden;
+  position:relative;
+}
+.highlights-wrap:before{
+  content:"";
+  position:absolute;
+  inset:-2px;
+  background:
+    radial-gradient(460px 260px at 16% 20%, rgba(242,201,76,.30), transparent 60%),
+    radial-gradient(480px 320px at 82% 28%, rgba(244,162,97,.28), transparent 62%),
+    radial-gradient(520px 380px at 50% 100%, rgba(255,255,255,.10), transparent 60%);
+  pointer-events:none;
+}
+.highlights-grid{
+  position:relative;
+  display:grid;grid-template-columns:1fr;
+  gap:14px;
+  padding:26px;
+}
+.stat{
+  background:rgba(255,255,255,.08);
+  border:1px solid rgba(255,255,255,.12);
+  border-radius:18px;
+  padding:16px 16px;
+  display:flex;gap:14px;align-items:flex-start
+}
+.stat-number{font-size:26px;font-weight:900;letter-spacing:-.02em;line-height:1.0}
+.stat-label{font-weight:850}
+.stat-desc{margin:2px 0 0;color:rgba(255,255,255,.82);font-size:13px}
+
+/* Featured products carousel */
+.carousel-shell{margin-top:22px}
+.carousel-top{display:flex;align-items:flex-end;justify-content:space-between;gap:14px}
+.carousel-actions{display:flex;gap:10px}
+.carousel-btn{
+  width:44px;height:44px;border-radius:999px;
+  display:inline-flex;align-items:center;justify-content:center;
+  border:1px solid rgba(14,27,20,.14);
+  background:rgba(255,255,255,.72);
+  box-shadow:var(--shadow-soft);
+  cursor:pointer;
+  transition:transform .12s ease, box-shadow .12s ease;
+}
+.carousel-btn:hover{transform:translateY(-1px);box-shadow:0 16px 34px rgba(14,27,20,.12)}
+.carousel-btn:active{transform:translateY(0)}
+.carousel-btn:focus{outline:none;box-shadow:0 0 0 6px var(--ring), var(--shadow-soft)}
+.carousel-btn[disabled]{opacity:.45;cursor:not-allowed;transform:none}
+
+.carousel-viewport{
+  margin-top:14px;
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(14,27,20,.10);
+  background:rgba(255,255,255,.40);
+  box-shadow:var(--shadow);
+  padding:14px;
+  overflow:hidden;
+}
+
+.carousel-track{
+  display:flex;
+  gap:14px;
+  overflow:auto;
+  scroll-behavior:smooth;
+  scroll-snap-type:x mandatory;
+  padding-bottom:6px;
+}
+.carousel-track::-webkit-scrollbar{height:10px}
+.carousel-track::-webkit-scrollbar-thumb{background:rgba(45,106,79,.28);border-radius:999px}
+.carousel-track::-webkit-scrollbar-track{background:rgba(14,27,20,.06);border-radius:999px}
+
+.product-card{
+  scroll-snap-align:start;
+  min-width:260px;
+  max-width:260px;
+  border-radius:20px;
+  border:1px solid rgba(14,27,20,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.92), rgba(255,255,255,.72));
+  box-shadow:0 16px 44px rgba(14,27,20,.12);
+  overflow:hidden;
+  display:flex;
+  flex-direction:column;
+}
+.product-photo{height:150px;background-size:cover;background-position:center;position:relative}
+.product-photo:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg, transparent 36%, rgba(14,27,20,.14))}
+.product-body{padding:14px 14px 12px;display:flex;flex-direction:column;gap:8px;flex:1}
+.product-title{margin:0;font-weight:900;letter-spacing:-.02em;font-size:16px}
+.product-desc{margin:0;color:var(--muted);font-size:13px;line-height:1.35}
+.product-footer{display:flex;align-items:center;justify-content:space-between;margin-top:auto;padding-top:8px}
+.price{font-weight:950;letter-spacing:-.02em}
+.tag{
+  font-size:12px;
+  font-weight:850;
+  color:rgba(45,106,79,.98);
+  background:rgba(45,106,79,.10);
+  border:1px solid rgba(45,106,79,.16);
+  padding:6px 10px;
+  border-radius:999px;
+}
+
+/* Seasonal picks */
+.picks{margin-top:22px;display:grid;grid-template-columns:1fr;gap:14px}
+.pick-card{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(14,27,20,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.78), rgba(255,255,255,.54));
+  box-shadow:var(--shadow);
+  padding:18px;
+  display:flex;gap:14px;align-items:flex-start
+}
+.pick-emoji{width:46px;height:46px;border-radius:16px;display:grid;place-items:center;
+  background:rgba(242,201,76,.30);
+  border:1px solid rgba(242,201,76,.35);
+  box-shadow:0 16px 40px rgba(242,201,76,.16);
+  font-size:22px
+}
+.pick-card h3{margin:0;font-size:16px;letter-spacing:-.02em}
+.pick-card p{margin:4px 0 0;color:var(--muted);font-size:13px}
+.pick-price{margin-top:10px;font-weight:950;color:var(--primary)}
+
+/* Categories */
+.categories-grid{margin-top:22px;display:grid;grid-template-columns:1fr;gap:14px}
+.category{
+  position:relative;
+  border-radius:var(--radius-xl);
+  overflow:hidden;
+  border:1px solid rgba(14,27,20,.10);
+  min-height:170px;
+  box-shadow:var(--shadow);
+  transform:translateZ(0);
+}
+.category .bg{position:absolute;inset:0;background-size:cover;background-position:center;filter:saturate(1.02) contrast(1.02)}
+.category .overlay{
+  position:absolute;inset:0;
+  background:linear-gradient(180deg, rgba(14,27,20,.05), rgba(14,27,20,.42));
+  opacity:.0;
+  transition:opacity .18s ease;
+}
+.category .content{position:relative;padding:18px;display:flex;flex-direction:column;justify-content:flex-end;height:170px}
+.category h3{margin:0;color:#fff;font-size:18px;letter-spacing:-.02em}
+.category p{margin:6px 0 0;color:rgba(255,255,255,.86);font-size:13px;max-width:46ch}
+.category{
+  transition:transform .18s ease, box-shadow .18s ease;
+}
+.category:hover{transform:scale(1.02);box-shadow:0 26px 70px rgba(14,27,20,.16)}
+.category:hover .overlay{opacity:1}
+.category:focus-within{box-shadow:0 0 0 6px var(--ring), 0 26px 70px rgba(14,27,20,.16)}
+.category a{position:absolute;inset:0;z-index:5}
+.category a:focus{outline:none}
+
+/* Store locator */
+.panel{
+  margin-top:22px;
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(14,27,20,.10);
+  background:linear-gradient(180deg, rgba(255,255,255,.74), rgba(255,255,255,.52));
+  box-shadow:var(--shadow);
+  padding:18px;
+}
+
+.form-row{display:flex;flex-direction:column;gap:10px}
+.input{
+  width:100%;
+  padding:12px 14px;
+  border-radius:16px;
+  border:1px solid rgba(14,27,20,.16);
+  background:rgba(255,255,255,.88);
+  font-weight:650;
+  font-size:14px;
+  box-shadow:0 12px 26px rgba(14,27,20,.06);
+}
+.input:focus{outline:none;box-shadow:0 0 0 6px var(--ring), 0 12px 26px rgba(14,27,20,.08);border-color:rgba(45,106,79,.35)}
+.help{margin:10px 0 0;color:var(--muted-2);font-size:13px}
+
+.results{margin-top:16px;display:grid;gap:12px}
+.store{
+  display:grid;gap:10px;
+  padding:14px;
+  border-radius:18px;
+  background:rgba(255,255,255,.70);
+  border:1px solid rgba(14,27,20,.10);
+}
+.store h4{margin:0;font-size:15px;letter-spacing:-.02em}
+.store-meta{display:grid;gap:8px;color:var(--muted);font-size:13px}
+.store-badges{display:flex;flex-wrap:wrap;gap:8px}
+.mini{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:8px 10px;border-radius:999px;
+  background:rgba(242,201,76,.20);
+  border:1px solid rgba(242,201,76,.22);
+  font-weight:850;font-size:12px;color:rgba(14,27,20,.85)
+}
+.mini.alt{background:rgba(244,162,97,.18);border-color:rgba(244,162,97,.24)}
+.mini.green{background:rgba(45,106,79,.12);border-color:rgba(45,106,79,.18)}
+
+/* Newsletter */
+.toast{
+  margin-top:12px;
+  padding:12px 14px;
+  border-radius:16px;
+  border:1px solid rgba(45,106,79,.22);
+  background:rgba(45,106,79,.10);
+  color:rgba(14,27,20,.88);
+  font-weight:800;
+  display:none;
+}
+.toast.show{display:block}
+
+/* Footer */
+footer{padding:42px 0 46px;border-top:1px solid rgba(14,27,20,.10)}
+.footer-grid{display:grid;grid-template-columns:1fr;gap:18px}
+.footer-card{
+  border-radius:var(--radius-xl);
+  border:1px solid rgba(14,27,20,.10);
+  background:rgba(255,255,255,.50);
+  box-shadow:var(--shadow);
+  padding:18px;
+}
+.footer-card h3{margin:0 0 8px;font-size:14px;letter-spacing:-.01em}
+.footer-links{display:flex;flex-wrap:wrap;gap:10px}
+.footer-links a{font-size:13px;color:var(--muted);font-weight:650}
+.footer-links a:hover{color:var(--text);text-decoration:none}
+.footer-bottom{margin-top:14px;color:var(--muted-2);font-size:13px}
+
+/* Responsive */
+@media (min-width: 820px){
+  .nav{display:flex}
+  .hero-grid{grid-template-columns:1.12fr .88fr;gap:34px}
+  .hero h1{font-size:56px}
+  .highlights-grid{grid-template-columns:repeat(4, 1fr)}
+  .stat{flex-direction:column;gap:10px}
+  .stat-number{font-size:34px}
+  .picks{grid-template-columns:repeat(2, 1fr)}
+  .categories-grid{grid-template-columns:repeat(3, 1fr)}
+  .category .content{height:190px}
+  .category{min-height:190px}
+  .form-row{flex-direction:row;align-items:center}
+  .form-row .input{flex:1}
+  .footer-grid{grid-template-columns:repeat(4, 1fr)}
+}
+
+@media (prefers-reduced-motion: reduce){
+  html{scroll-behavior:auto}
+  .btn,.carousel-btn,.category{transition:none}
+  .carousel-track{scroll-behavior:auto}
+}
+
*** End Patch
PATCH

